<style>.em-report-bar{height:12px;background:#e5e7eb;border-radius:6px;overflow:hidden}.em-report-bar span{display:block;height:100%;background:#2563eb}</style><div class="page-title clearfix"><h1>Email Marketing Reports</h1><div class="title-button-group"><a class="btn btn-default" href="<?php echo site_url('email_marketing/dashboard'); ?>">Dashboard</a><a class="btn btn-default" href="<?php echo site_url('email_marketing/reports/export'); ?>">Export delivery CSV</a></div></div>
<div class="row"><?php foreach($totals as $name=>$value): ?><div class="col-md-2"><div class="card"><div class="card-body"><div><?php echo ucfirst($name); ?></div><h2><?php echo (int)$value; ?></h2></div></div></div><?php endforeach; ?></div>
<?php $report_max=max(1,max($totals)); ?><div class="card mt15"><div class="card-header"><h4>Delivery totals</h4></div><div class="card-body"><?php foreach($totals as $name=>$value): ?><div class="mb10"><div><?php echo ucfirst($name); ?> (<?php echo (int)$value; ?>)</div><div class="em-report-bar"><span style="width:<?php echo (int)round(($value/$report_max)*100); ?>%"></span></div></div><?php endforeach; ?></div></div>
<div class="card mt15"><div class="card-header"><h4>Campaign delivery breakdown</h4></div><div class="table-responsive"><table class="table"><thead><tr><th>Campaign</th><th>Campaign status</th><th>Queued</th><th>Sent</th><th>Failed</th><th>Skipped</th><th>Unsubscribed</th><th>Log</th></tr></thead><tbody><?php foreach($campaigns as $c): $b=$breakdowns[$c->id]??[]; ?><tr><td><?php echo esc($c->name); ?></td><td><?php echo esc($c->status); ?></td><td><?php echo (int)($b['queued']??0); ?></td><td><?php echo (int)($b['sent']??0); ?></td><td><?php echo (int)($b['failed']??0); ?></td><td><?php echo (int)($b['skipped']??0); ?></td><td><?php echo (int)($b['unsubscribed']??0); ?></td><td><a href="<?php echo site_url('email_marketing/logs/'.$c->id); ?>">View log</a></td></tr><?php endforeach; if(!$campaigns): ?><tr><td colspan="8">No campaign data.</td></tr><?php endif; ?></tbody></table></div></div>
